expressionInfos.expression:
var amenities = []
if ($feature.RAMP == "Yes") {Push(amenities, "Trailered Boat Ramp")}
if ($feature.HAND == "Yes") {Push(amenities, "Hand Carry Boat Launch")}
if ($feature.PARKING == "Yes") {Push(amenities, "Parking")}
if ($feature.SANITATION == "Yes") {Push(amenities, "Sanitation")}
if ($feature.USEFEE == "Yes") {Push(amenities, "Use Fee")}
if ($feature.PFD == "Yes") {Push(amenities, "PFD Loaner Station")}
if ($feature.WINDSURF == "Yes") {Push(amenities, "Wind Surfing")}
if ($feature.POLESLIDE == "Yes") {Push(amenities, "Boat Slide Launch")}
return Concatenate(amenities, ", ")

var amenitiesm = []
if ($feature.CLEAN == "Yes") {Push(amenitiesm, "Certified Clean Marina")}
