if ($feature.CVA == "Yes") {Push(amenitiesm, "Pumpout Dumpstation")}
if ($feature.FUEL == "Yes") {Push(amenitiesm, "On-Water Fuel")}
if ($feature.HOIST == "Yes") {Push(amenitiesm, "Hoist")}
return Concatenate(amenitiesm, ", ")
